import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load brushed-metal texture map
  const metalTexture = ctx.textureLoader.load(config.assets.imageUrl);

  // Create material using tsl texture node
  const material = new MeshBasicNodeMaterial({
    colorNode: texture(metalTexture),
    toneMapped: false
  });

  // Create plane geometry (atlas aspect ratio 512:320 = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.2, 0.75);
  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // Render text label via ctx.fontAtlas
  if (config.textContent && config.textContent.length > 0) {
    const textSpec = config.textContent[0];
    const textMesh = ctx.fontAtlas(config, {
      text: textSpec.content || 'Journal 1',
      fontFamily: 'Lora',
      fontSize: 0.34,
      fontWeight: 400,
      color: 0x16161d,
      align: 'center'
    });

    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Apply scene positioning
  if (config.scenePosition) {
    group.position.fromArray(config.scenePosition);
  }

  // Apply scene rotation
  if (config.sceneRotation) {
    group.rotation.fromArray(config.sceneRotation);
  }

  // Apply scene scale
  if (config.sceneScale) {
    group.scale.fromArray(config.sceneScale);
  }

  // Initialize handlers object
  group.userData.handlers = {};

  // Define cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    metalTexture.dispose();
  };

  return group;
}
